# Hypothesis: output = pattern copies tiled with period equal to tile height/width; overlapping cells become 8, others keep value. Let's test on all demos by constructing tiling: find period p (tile height). For each cell that has a copy covering it from another copy at offset, set 8.
def solve(i):
    i=np.array(i); H,W=i.shape
    # find tile height: smallest h>0 such that band starting at row h equals band starting at row 0
    h=None
    for hh in range(1,H):
        if (i[hh:hh+4]==i[0:4]).all(): break
    P=i[0:4]          # pattern rows
    O=i.copy()
    # place copies at rows r where i[r]==P? find anchor: copies are at rows 0,5?,9.. Check which rows' bands equal P shifted horizontally:
    out=O.copy()
    # determine tile width: columns where horizontal periodicity holds within top band
    pw=None
    cols=[]
    for c0 in range(W-6):
        if (P[:,c0:c0+7]==P[:,:7]).all(): cols.append(c0)
    # tile positions: collect all (r,c) copies
    copies=[]
    for r in range(H):
        for c in range(W-3):
            sub=i[r:r+4,c:c+7]
            if (sub==P[:,:7]).all():
                copies.append((r,c))
    # overlaps: two copies whose rectangles intersect -> cells in intersection become 8
    res=np.zeros_like(i)
    for r,c in copies:
        for rr in range(r,r+4):
            for cc in range(c,c+7):
                if i[rr,cc]==2: res[rr,cc]=2
    # recolor overlap intersections:
    cells=[]
    for r,c in copies:
        for rr in range(r,r+4):
            for cc in range(c,c+7):
                if any(rr-r0<=3 and cc-c0<=6 and rr>=r0 and cc>=c0 for r0,c0 in copies if (r0,c0)!=(r,c)):
                    cells.append((rr,cc))
    for rr,cc in cells:
        res[rr,cc]=8
    return [[int(v) for v in row] for row in res]
